SELECT * FROM (SELECT CASE WHEN YEAR(hire_date) < 2024 THEN 'before_2024' WHEN YEAR(hire_date) = 2024 THEN '2024' ELSE 'after_2024' END AS hire_cohort, dept_id, SUM(CASE WHEN job_title = 'Manager' THEN salary ELSE 0 END) AS manager_salary FROM employees GROUP BY CASE WHEN YEAR(hire_date) < 2024 THEN 'before_2024' WHEN YEAR(hire_date) = 2024 THEN '2024' ELSE 'after_2024' END, dept_id) AS agg WHERE manager_salary < 70 ORDER BY hire_cohort, manager_salary;
